        /// <param name="cancellationToken">Cancels the request.</param>
        public async Task<SessionsUpdateFeatureStatusResponse> UpdateFeatureStatusAsync(string sessionId, string nodeId, SessionsUpdateFeatureStatusParams parameters, RequestOptions? requestOptions = null, CancellationToken cancellationToken = default)
